<div class="card"><div class="card-header"><strong>Cómo se aplica</strong></div><div class="card-body"><div class="row g-3"><div class="col-md-4"><strong>1. Persona + unidad</strong><p class="text-body-secondary mb-0">Una persona puede ser propietaria de una unidad e inquilina de otra.</p></div><div class="col-md-4"><strong>2. Perfil + alcance</strong><p class="text-body-secondary mb-0">El perfil habilita cámaras/accesos comunes, de su torre, piso o unidad sin seleccionar recurso por recurso.</p></div><div class="col-md-4"><strong>3. Traducción tecnológica</strong><p class="text-body-secondary mb-0">Property Hub compila la intención y el Edge la ejecuta/provisiona según ZK, Vimar, relé u otro driver.</p></div></div></div></div>
<?php if(can('people.manage')):?><div class="modal fade" id="profileModal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><form method="post" action="<?=url('access-profile-save')?>"><?=csrf_field()?><input type="hidden" name="id" id="profileId"><div class="modal-header"><h5 class="modal-title" id="profileTitle">Nuevo perfil</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-3"><label class="form-label">Código</label><input class="form-control" name="code" id="profileCode" required></div><div class="col-md-5"><label class="form-label">Nombre</label><input class="form-control" name="name" id="profileName" required></div><div class="col-md-4"><label class="form-label">Basado en</label><select class="form-select" name="parent_profile_id" id="profileParent"><option value="">Sin perfil base</option><?php foreach($options as $o):?><option value="<?=e($o['id'])?>"><?=e($o['name'])?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label">Sólo para esta propiedad/unidad</label><select class="form-select" name="scope_property_id" id="profileScopeProperty"><option value="">Toda la instalación</option><?php foreach($properties as $o):?><option value="<?=e($o['id'])?>"><?=e($o['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Relación sugerida</label><select class="form-select" name="relationship_hint" id="profileRelation"><option value="">Ninguna</option><?php foreach(['owner','tenant','resident','family','domestic_staff','driver','maintenance','authorized'] as $r):?><option value="<?=e($r)?>"><?=e(relationship_label($r))?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Estado</label><select class="form-select" name="status" id="profileStatus"><option value="active">Activo</option><option value="inactive">Inactivo</option></select></div><div class="col-12"><label class="form-label">Descripción</label><input class="form-control" name="description" id="profileDescription"></div><div class="col-12"><hr><strong>Capacidades</strong></div><?php foreach(['can_invite'=>'Generar invitaciones','can_reserve'=>'Reservar áreas','can_view_notifications'=>'Ver notificaciones','can_view_documents'=>'Ver documentos','can_use_domotics'=>'Usar domótica'] as $n=>$l):?><div class="col-md-auto"><label class="form-check"><input class="form-check-input cap" type="checkbox" name="<?=$n?>" id="<?=$n?>"><span class="form-check-label"><?=e($l)?></span></label></div><?php endforeach;?><div class="col-12"><hr></div><div class="col-md-6"><strong>Cámaras permitidas por alcance</strong><div class="row mt-2"><?php foreach($scopeLabels as $v=>$l):?><div class="col-md-6"><label class="form-check"><input class="form-check-input camScope" type="checkbox" name="camera_scopes[]" value="<?=e($v)?>"><span class="form-check-label"><?=e($l)?></span></label></div><?php endforeach;?></div></div><div class="col-md-6"><strong>Accesos permitidos por alcance</strong><div class="row mt-2"><?php foreach($scopeLabels as $v=>$l):?><div class="col-md-6"><label class="form-check"><input class="form-check-input accScope" type="checkbox" name="access_scopes[]" value="<?=e($v)?>"><span class="form-check-label"><?=e($l)?></span></label></div><?php endforeach;?></div><div class="row g-2 mt-2"><div class="col-5"><label class="form-label">Días 1=Lun ... 7=Dom</label><input class="form-control" name="access_days" id="accessDays" value="1,2,3,4,5,6,7"></div><div class="col"><label class="form-label">Desde</label><input class="form-control" type="time" name="access_start" id="accessStart" value="00:00"></div><div class="col"><label class="form-label">Hasta</label><input class="form-control" type="time" name="access_end" id="accessEnd" value="23:59"></div></div></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar perfil</button></div></form></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const m=document.getElementById('profileModal');m.addEventListener('show.bs.modal',e=>{let d={};const b=e.relatedTarget;if(b?.classList.contains('js-edit-profile')){try{d=JSON.parse(b.dataset.json||'{}')}catch(x){}}document.getElementById('profileTitle').textContent=d.id?'Editar perfil':'Nuevo perfil';for(const [id,k] of Object.entries({profileId:'id',profileCode:'code',profileName:'name',profileParent:'parent_profile_id',profileScopeProperty:'scope_property_id',profileRelation:'relationship_hint',profileStatus:'status',profileDescription:'description'}))document.getElementById(id).value=d[k]??(id==='profileStatus'?'active':'');document.querySelectorAll('.cap,.camScope,.accScope').forEach(x=>x.checked=false);for(const id of ['can_invite','can_reserve','can_view_notifications','can_view_documents','can_use_domotics'])document.getElementById(id).checked=!!Number(d[id]||0);const rules=d.rules||[];for(const r of rules){const cls=r.resource_domain==='camera'?'.camScope':'.accScope';const x=[...document.querySelectorAll(cls)].find(y=>y.value===r.scope_type);if(x)x.checked=true;if(r.resource_domain==='access'){document.getElementById('accessDays').value=r.days_of_week||'1,2,3,4,5,6,7';document.getElementById('accessStart').value=(r.start_time||'00:00').slice(0,5);document.getElementById('accessEnd').value=(r.end_time||'23:59').slice(0,5);}}});});</script><?php endif;?>
